"""Create a correctly structured source ZIP for a GitHub repository upload."""
from pathlib import Path
from zipfile import ZipFile,ZIP_DEFLATED
import shutil
from scripts.package_site import ROOT,site_files,REPOSITORY_DOWNLOADS


def package():
    # Forecast assets are regenerated by Actions; source uploads stay small.
    files=set(site_files(include_generated=False))
    files.update(ROOT/name for name in REPOSITORY_DOWNLOADS if (ROOT/name).is_file())
    files.update(ROOT/path for path in ['.gitignore','.github/workflows/sunset.yml',
                  'requirements-sunset.txt','requirements-sunset-dev.txt'])
    files.update((ROOT/'.github/workflows').glob('*.yml'))
    for directory in ['sunset','weather','models','tropical','centers','analysis','ensembles','enso','specialty','seasonal','optics','scripts','tests']:
        files.update((ROOT/directory).glob('*.py'))
    files.add(ROOT/'sunset/cities.json')
    files.add(ROOT/'requirements-seasonal-external.txt')
    files.update(p for p in (ROOT/'radar').glob('*') if p.is_file() and p.suffix in {'.mjs','.json','.txt'})
    out=ROOT/'output/ch-weather-github-ready.zip'
    out.parent.mkdir(parents=True,exist_ok=True)
    with ZipFile(out,'w',ZIP_DEFLATED) as archive:
        for path in sorted(files): archive.write(path,path.relative_to(ROOT).as_posix())
    print(f'Packaged {len(files)} GitHub source/website files: {out}')
    ordered=sorted(files)
    for start in range(0,len(ordered),90):
        batch=out.parent/f'ch-weather-upload-batch-{start//90+1}.zip'
        with ZipFile(batch,'w',ZIP_DEFLATED) as archive:
            for path in ordered[start:start+90]:
                archive.write(path,path.relative_to(ROOT).as_posix())
        print(f'Upload batch: {batch.name} ({len(ordered[start:start+90])} files)')
    for workflow in (ROOT/'.github/workflows').glob('*.yml'):
        shutil.copy2(workflow,out.parent/workflow.name)
    changed=['.github/workflows/sunset.yml','.github/workflows/models.yml','.github/workflows/publish.yml',
             'models/__main__.py','scripts/merge_models.py','scripts/collect_publication.py','scripts/package_github.py',
             'tests/test_independent_publication.py','tests/test_packaging.py','tests/test_model_selection.py',
             'README.md','docs/REFRESHES.md','docs/MODELS.md','docs/FIX-AUTOMATIC-UPDATES.md']
    changed=sorted(set(changed+['weather/sources.py','weather/__main__.py','weather/render.py',
        'scripts/package_site.py','assets/models.js','assets/outlooks.js','tests/test_weather.py','docs/PARTIAL-UPDATES.md']))
    with ZipFile(out.parent/'ch-weather-model-split-update.zip','w',ZIP_DEFLATED) as archive:
        for name in changed:archive.write(ROOT/name,name)
    shutil.copy2(out.parent/'ch-weather-model-split-update.zip',out.parent/'ch-weather-reliable-updates.zip')
    collection=['index.html','sunset/index.html','outlooks/index.html','outlooks/centers.html','outlooks/collection.html',
        'tropical/index.html','alerts/index.html','mos/index.html','enso/index.html',
        'assets/collection.css','assets/collection.js','assets/navigation.css','assets/navigation.js',
        '.github/workflows/sunset.yml','requirements-sunset.txt','scripts/package_site.py','scripts/collect_publication.py',
        'scripts/package_github.py','scripts/run_product.py','tests/test_specialty.py','tests/test_packaging.py',
        'tests/test_independent_publication.py','README.md','docs/OUTLOOK-COLLECTION.md']
    collection.extend(p.relative_to(ROOT).as_posix() for p in (ROOT/'specialty').glob('*.py'))
    with ZipFile(out.parent/'ch-weather-outlook-collection-update.zip','w',ZIP_DEFLATED) as archive:
        for name in sorted(set(collection)):archive.write(ROOT/name,name)
    portfolio=['portfolio/index.html','portfolio/projects.html','portfolio/gis-tornado-shelters.html',
        'portfolio/norman-tornado-environments.html','portfolio/charlotte-land-cover.html',
        'assets/project-detail.css','assets/project-viewer.js','scripts/package_site.py',
        'scripts/package_github.py','tests/test_packaging.py','docs/PORTFOLIO-PROJECTS.md']
    portfolio.extend(p.relative_to(ROOT).as_posix() for p in (ROOT/'assets/projects').rglob('*') if p.is_file())
    with ZipFile(out.parent/'ch-weather-portfolio-projects-update.zip','w',ZIP_DEFLATED) as archive:
        for name in sorted(set(portfolio)):archive.write(ROOT/name,name)

    seasonal=['seasonal/index.html','assets/seasonal.css','assets/seasonal.js','assets/navigation.js',
        'enso/index.html','.github/workflows/seasonal.yml','.github/workflows/publish.yml',
        'scripts/package_site.py','scripts/package_github.py','tests/test_packaging.py',
        'tests/test_seasonal.py','tests/test_seasonal_verification.py','docs/SEASONAL.md','docs/SEASONAL-V3.md','requirements-seasonal-external.txt','README.md']
    seasonal.extend(p.relative_to(ROOT).as_posix() for p in (ROOT/'seasonal').glob('*.py'))
    with ZipFile(out.parent/'ch-weather-seasonal-update.zip','w',ZIP_DEFLATED) as archive:
        for name in sorted(set(seasonal)):archive.write(ROOT/name,name)
    shutil.copy2(out.parent/'ch-weather-seasonal-update.zip',out.parent/'ch-weather-blend-update.zip')

    optics=['optics/index.html','assets/optics.js','assets/optics.css','assets/navigation.js',
        'outlooks/index.html','.github/workflows/sunset.yml','scripts/package_site.py',
        'scripts/package_github.py','tests/test_optics.py','tests/test_optics_context.py','docs/SOLAR-OPTICS.md','README.md']
    optics.extend(p.relative_to(ROOT).as_posix() for p in (ROOT/'optics').glob('*.py'))
    with ZipFile(out.parent/'ch-weather-solar-optics-update.zip','w',ZIP_DEFLATED) as archive:
        for name in sorted(set(optics)):archive.write(ROOT/name,name)



if __name__=='__main__':package()
